CREATE TABLE "DesktopNote" ("id" TEXT NOT NULL PRIMARY KEY,"userId" TEXT NOT NULL,"content" TEXT NOT NULL DEFAULT '',"template" TEXT NOT NULL DEFAULT 'blank',"revision" INTEGER NOT NULL DEFAULT 0,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "DesktopNote_userId_idx" ON "DesktopNote"("userId");
CREATE TABLE "CalendarEvent" ("id" TEXT NOT NULL PRIMARY KEY,"userId" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL DEFAULT '',"startsAt" DATETIME NOT NULL,"endsAt" DATETIME,"allDay" BOOLEAN NOT NULL DEFAULT false,"dateKey" TEXT NOT NULL,"timeZone" TEXT NOT NULL,"noteId" TEXT,"revision" INTEGER NOT NULL DEFAULT 0,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY("noteId") REFERENCES "DesktopNote"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX "CalendarEvent_userId_startsAt_idx" ON "CalendarEvent"("userId","startsAt");
CREATE TABLE "EventReminder" ("id" TEXT NOT NULL PRIMARY KEY,"eventId" TEXT NOT NULL,"offsetMinutes" INTEGER NOT NULL,"scheduledAt" DATETIME NOT NULL,"deliveredAt" DATETIME,"claimUntil" DATETIME,"claimToken" TEXT,FOREIGN KEY("eventId") REFERENCES "CalendarEvent"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "EventReminder_eventId_key" ON "EventReminder"("eventId");
CREATE INDEX "EventReminder_deliveredAt_scheduledAt_idx" ON "EventReminder"("deliveredAt","scheduledAt");